fn agx_default_contrast(x: vec3<f32>) -> vec3<f32> {
    let x2 = x * x;
    let x4 = x2 * x2;
    return 15.5 * x4 * x2 - 40.14 * x4 * x + 31.96 * x4 - 6.868 * x2 * x + 0.4298 * x2 + 0.1191 * x - 0.00232;
}

fn agx_tonemap(val_in: vec3<f32>) -> vec3<f32> {
    let inset = mat3x3<f32>(vec3<f32>(0.84247906, 0.04232824, 0.04237565), vec3<f32>(0.0784336, 0.87846864, 0.0784336), vec3<f32>(0.07922375, 0.07916613, 0.87914297));
    let outset = mat3x3<f32>(vec3<f32>(1.196879, -0.05289685, -0.05297163), vec3<f32>(-0.09802088, 1.15190313, -0.09804345), vec3<f32>(-0.09902975, -0.09896118, 1.15107367));
    var v = max(inset * max(val_in, vec3<f32>(0.0)), vec3<f32>(1e-6));
    v = clamp((log2(v) + 12.47393) / 16.5, vec3<f32>(0.0), vec3<f32>(1.0));
    v = agx_default_contrast(v);
    v = max(outset * v, vec3<f32>(0.0));
    return saturate(pow(v, vec3<f32>(2.2)));
}

